class Solution {
public:
    int catMouseGame(vector<vector<int>>& graph) {
        int n = graph.size();
        int color[50][50][3] = {0};
        int degree[50][50][3] = {0};
        for (int m = 0; m < n; m++) {
            for (int c = 0; c < n; c++) {
                degree[m][c][1] = graph[m].size();
                degree[m][c][2] = graph[c].size();
                for (int x : graph[c]) if (x == 0) degree[m][c][2]--;
            }
        }
        queue<tuple<int, int, int, int>> q;
        for (int c = 1; c < n; c++) {
            color[0][c][1] = color[0][c][2] = 1;
            q.push({0, c, 1, 1});
            q.push({0, c, 2, 1});
            color[c][c][1] = color[c][c][2] = 2;
            q.push({c, c, 1, 2});
            q.push({c, c, 2, 2});
        }
        while (!q.empty()) {
            auto [m, c, turn, result] = q.front();
            q.pop();
            if (m == 1 && c == 2 && turn == 1) return result;
            int prev_turn = (turn == 1) ? 2 : 1;
            vector<pair<int, int>> parents;
            if (prev_turn == 1) {
                for (int pm : graph[m]) parents.push_back({pm, c});
            } else {
                for (int pc : graph[c]) if (pc != 0) parents.push_back({m, pc});
            }
            for (auto [pm, pc] : parents) {
                if (color[pm][pc][prev_turn] != 0) continue;
                if ((prev_turn == 1 && result == 1) || (prev_turn == 2 && result == 2)) {
                    color[pm][pc][prev_turn] = result;
                    q.push({pm, pc, prev_turn, result});
                } else {
                    degree[pm][pc][prev_turn]--;
                    if (degree[pm][pc][prev_turn] == 0) {
                        int lose_res = (prev_turn == 1) ? 2 : 1;
                        color[pm][pc][prev_turn] = lose_res;
                        q.push({pm, pc, prev_turn, lose_res});
                    }
                }
            }
        }
        return 0;
    }
};

class Solution {
    public int catMouseGame(int[][] graph) {
        int n = graph.length;
        int[][][] color = new int[n][n][3];
        int[][][] degree = new int[n][n][3];
        for (int m = 0; m < n; m++) {
            for (int c = 0; c < n; c++) {
                degree[m][c][1] = graph[m].length;
                degree[m][c][2] = graph[c].length;
                for (int x : graph[c]) if (x == 0) degree[m][c][2]--;
            }
        }
        Queue<int[]> q = new LinkedList<>();
        for (int c = 1; c < n; c++) {
            color[0][c][1] = color[0][c][2] = 1;
            q.offer(new int[]{0, c, 1, 1});
            q.offer(new int[]{0, c, 2, 1});
            color[c][c][1] = color[c][c][2] = 2;
            q.offer(new int[]{c, c, 1, 2});
            q.offer(new int[]{c, c, 2, 2});
        }
        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int m = curr[0], c = curr[1], turn = curr[2], result = curr[3];
            if (m == 1 && c == 2 && turn == 1) return result;
            int prevTurn = (turn == 1) ? 2 : 1;
            List<int[]> parents = new ArrayList<>();
            if (prevTurn == 1) {
                for (int pm : graph[m]) parents.add(new int[]{pm, c});
            } else {
                for (int pc : graph[c]) if (pc != 0) parents.add(new int[]{m, pc});
            }
            for (int[] p : parents) {
                int pm = p[0], pc = p[1];
                if (color[pm][pc][prevTurn] != 0) continue;
                if ((prevTurn == 1 && result == 1) || (prevTurn == 2 && result == 2)) {
                    color[pm][pc][prevTurn] = result;
                    q.offer(new int[]{pm, pc, prevTurn, result});
                } else {
                    degree[pm][pc][prevTurn]--;
                    if (degree[pm][pc][prevTurn] == 0) {
                        int loseRes = (prevTurn == 1) ? 2 : 1;
                        color[pm][pc][prevTurn] = loseRes;
                        q.offer(new int[]{pm, pc, prevTurn, loseRes});
                    }
                }
            }
        }
        return 0;
    }
}

var catMouseGame = function(graph) {
    const n = graph.length;
    const color = Array.from({ length: n }, () => Array.from({ length: n }, () => [0, 0, 0]));
