        q.push([0, c, 2, 1]);
        color[c][c][1] = color[c][c][2] = 2;
        q.push([c, c, 1, 2]);
        q.push([c, c, 2, 2]);
    }
    while (q.length > 0) {
        const [m, c, turn, result] = q.shift();
        if (m === 1 && c === 2 && turn === 1) return result;
        const prevTurn = turn === 1 ? 2 : 1;
        const parents = [];
        if (prevTurn === 1) {
            for (const pm of graph[m]) parents.push([pm, c]);
